pub fn ct_groupcompletion_checkpoint_fires_under_faithful_corpus_test() -> String {
    v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("    #[test]\n".to_string(), "    fn groupcompletion_int_checkpoint_fires_under_faithful_corpus() {\n".to_string()), "        // Discriminating witness for the (b) checkpoint-order fix (sharp-bee-290 sign-off,\n".to_string()), "        // msg_6fc2ba88-549b-491e-9b6f-ab949539d682): emit_typed_item's zero-param alias-decl\n".to_string()), "        // branch calls rust_scalar_checkpoint_render_base (the single-authority checkpoint\n".to_string()), "        // lookup), not the HostNative-only rust_seed_host_numeric_alias, so the Int -> i64\n".to_string()), "        // checkpoint row (dag/extdeps/languages/rust/types.dag) fires BEFORE the RHS\n".to_string()), "        // (GroupCompletion<Nat>) is unfolded — under BOTH corpus representations. A\n".to_string()), "        // regression that narrows this back to the HostNative-only alias makes the\n".to_string()), "        // FaithfulFreeMonoid arm return None, which is what this witness guards.\n".to_string()), "        assert_eq!(\n".to_string()), "            crate::v1_compiler_emit_rust::rust_scalar_checkpoint_render_base(\n".to_string()), "                \"Int\".to_string(),\n".to_string()), "                crate::v1_compiler_infer_emit_info::RustCorpusRepr::FaithfulFreeMonoid\n".to_string()), "            ),\n".to_string()), "            Some(\"i64\".to_string())\n".to_string()), "        );\n".to_string()), "        assert_eq!(\n".to_string()), "            crate::v1_compiler_emit_rust::rust_scalar_checkpoint_render_base(\n".to_string()), "                \"Int\".to_string(),\n".to_string()), "                crate::v1_compiler_infer_emit_info::RustCorpusRepr::HostNative\n".to_string()), "            ),\n".to_string()), "            Some(\"i64\".to_string())\n".to_string()), "        );\n".to_string()), "        // GroupCompletion itself has no checkpoint row and is not the seed host numeric\n".to_string()), "        // alias, so the checkpoint correctly declines to render it directly (the RHS\n".to_string()), "        // unfolding path handles it as a real 2-field struct) — the checkpoint fires ONLY\n".to_string()), "        // for the Int/Nat leaf name, never widening to the container type.\n".to_string()), "        assert_eq!(\n".to_string()), "            crate::v1_compiler_emit_rust::rust_scalar_checkpoint_render_base(\n".to_string()), "                \"GroupCompletion\".to_string(),\n".to_string()), "                crate::v1_compiler_infer_emit_info::RustCorpusRepr::FaithfulFreeMonoid\n".to_string()), "            ),\n".to_string()), "            None\n".to_string()), "        );\n".to_string()), "    }\n\n".to_string())
}

